import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.doxMM-x8.js";const b=JSON.parse('{"title":"Development And Validation","description":"","frontmatter":{"docLocale":"en","counterpart":"/testing/feedback-loop","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/testing/feedback-loop.md","filePath":"en/testing/feedback-loop.md"}'),n={name:"en/testing/feedback-loop.md"};function r(i,e,s,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="development-and-validation" tabindex="-1">Development And Validation <a class="header-anchor" href="#development-and-validation" aria-label="Permalink to &quot;Development And Validation&quot;">​</a></h1><p>Goal: select public checks that observe your Lab Word change. Run from the repository root. The <a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/docs/testing/strategy.md" target="_blank" rel="noreferrer">testing strategy</a>defines responsibilities.</p><h2 id="choose-an-entry" tabindex="-1">Choose An Entry <a class="header-anchor" href="#choose-an-entry" aria-label="Permalink to &quot;Choose An Entry&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Change</th><th>Command</th><th>Evidence and prerequisites</th></tr></thead><tbody><tr><td>Web behavior</td><td><code>pnpm test:frontend</code></td><td>Real component interaction; HTTP uses MSW</td></tr><tr><td>TypeScript and boundaries</td><td><code>pnpm typecheck</code>, <code>pnpm boundaries:check</code></td><td>Types, package dependencies, Rust table ownership</td></tr><tr><td>Backend behavior</td><td><code>node scripts/test-backend.mjs --test registration</code></td><td>Real Router and isolated services; requires Docker</td></tr><tr><td>Contracts</td><td><code>pnpm generate</code>, <code>pnpm contracts:check</code></td><td>Rust/OpenAPI, generated types and SDK agree; includes Rust generation</td></tr><tr><td>Documentation</td><td><code>pnpm docs:check</code>, <code>pnpm docs:build</code></td><td>Sources, locale pairing, generated references and built links; may compile Rust</td></tr><tr><td>Documentation browser journeys</td><td><code>just e2e-docs</code></td><td>Language, theme, search, agreed viewports, custom base; requires Chromium</td></tr><tr><td>Critical application journeys</td><td><code>just e2e</code></td><td>Real Web/API/Worker/database/storage; requires Docker and Chromium</td></tr></tbody></table><p>Install browser prerequisites with <code>pnpm exec playwright install chromium</code>. <code>just check</code> runs main formatting, static, behavior, budget and build checks without browser E2E. <code>just check-full</code> adds application E2E.</p><p>Command capabilities do not expand task scope. Validate desktop web by default; include mobile adaptation, narrow screens, touch or real devices only within explicitly approved scope. Check discovery and prerequisites before heavy browser runs. Reuse existing critical journeys; use focused cases for affected CSS or layout states.</p><p><code>docs:check</code> and <code>docs:build</code> invoke <code>cargo run --quiet --locked -p labos-threejs-api --bin config-reference</code>. These commands can compile Rust without Docker. Coordinate generation, documentation and full gates by their runtime dependencies. Use the agreed Cargo jobs and run supervisor; command names do not establish that a check is lightweight.</p><h2 id="lab-viewer-boundaries" tabindex="-1">Lab Viewer Boundaries <a class="header-anchor" href="#lab-viewer-boundaries" aria-label="Permalink to &quot;Lab Viewer Boundaries&quot;">​</a></h2><p>The accepted Viewer experience has rendering and lifecycle evidence in the <a href="./../guides/lab-viewer">separate preview</a>. Application checks in this documentation baseline do not cover production Lab; product integration needs its own validation.</p><p>Production component checks will observe import controls, selection, loading/error and recovery. Browser checks will observe real GLB/HDR, canvas pixels, camera and resource disposal. DOM success does not prove visible 3D rendering; one memory sample does not establish a leak.</p><h2 id="failure-and-evidence" tabindex="-1">Failure And Evidence <a class="header-anchor" href="#failure-and-evidence" aria-label="Permalink to &quot;Failure And Evidence&quot;">​</a></h2><p>Record commands, missing prerequisites and unverified scope when Docker, Chromium or dependencies are unavailable. Skipped checks are not passes. Backend checks use isolated resources and do not clean development or production data.</p><p>Record evidence against a fixed revision, environment and task scope. Reuse genuine TDD red and recovery green as VDD evidence for the same assertion. Local focused checks and one full gate in the responsible environment cover the stable final candidate. Reuse included affected checks. Refresh coverage by semantic impact after repairs or main changes. The <a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/docs/agents/development-flow.md" target="_blank" rel="noreferrer">development flow</a> defines the sequence and independent review.</p><p>Use <a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/.agents/skills/development-timeline/SKILL.md" target="_blank" rel="noreferrer">development-timeline</a> for lightweight stage, wait and rework records during multi-stage collaboration. Reports explain recorded progress and uncertainty; they do not add product validation or merge gates.</p><hr><p>Source version：<code>a455a4dba0f3</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/docs/testing/t01-feedback-loop.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>',16)])])}const h=t(n,[["render",r]]);export{b as __pageData,h as default};
